/**
 * Декоративна дужка, що обіймає блок-примітку.
 * preserveAspectRatio="none" — щоб розтягувалась на всю висоту блоку.
 */
export function BraceIcon({
  side = 'left',
  ...rest
}: SVGProps<SVGSVGElement> & { side?: 'left' | 'right' }) {
  return (
    <svg
      viewBox="0 0 24 200"
      preserveAspectRatio="none"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      vectorEffect="non-scaling-stroke"
      aria-hidden="true"
      style={side === 'right' ? { transform: 'scaleX(-1)' } : undefined}
      {...rest}
    >
      <path
        d="M22 1 C8 26, 1 68, 1 100 C1 132, 8 174, 22 199"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  )
}

